#include <iostream>
#include <cstdint>

using namespace std;

uint64_t powerOfTwoMST(uint64_t p) {
    if (p <= 1) return 0;

    unsigned exponent = 0;
    for (uint64_t x = p; x > 1; x >>= 1) {
        ++exponent;
    }

    return (p / 2) * exponent;
}

uint64_t xorMST(uint64_t n) {
    uint64_t result = 0;

    while (n > 1) {
        uint64_t p = 1;
        while (p <= n / 2) {
            p <<= 1;
        }

        if (p == n) {
            result += powerOfTwoMST(p);
            break;
        }

        result += powerOfTwoMST(p) + p;
        n -= p;
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    uint64_t n;
    cin >> n;

    cout << xorMST(n) << '\n';
    return 0;
}

#include <iostream>
#include <cstdint>

using namespace std;

uint64_t mstCost(uint64_t n) {
    if (n <= 1) return 0;

    uint64_t p = 1;
    uint64_t k = 0;

    while (p <= n / 2) {
        p <<= 1;
        ++k;
    }

    uint64_t fullBlockCost = (p / 2) * k;

    if (n == p) return fullBlockCost;

    return fullBlockCost + p + mstCost(n - p);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    uint64_t n;
    cin >> n;

    cout << mstCost(n) << '\n';
    return 0;
}

